-- One lock for config delivery and agent delete. A flush that already loaded a row must not
-- write the directory or the tenant object while delete is wiping them, and delete must not
-- start that wipe while a delivery is still writing. Append-only: do not edit this file.
CREATE TABLE IF NOT EXISTS control_locks (
  name TEXT PRIMARY KEY,
  holder TEXT NOT NULL,
  expires_ms INTEGER NOT NULL
);
INSERT INTO control_locks (name, holder, expires_ms) VALUES ('outbox', '', 0)
ON CONFLICT(name) DO NOTHING;
